export function Modal({ open, onClose, title, children }) {
  if (!open) return null;
  return (
    <div className="backdrop" onClick={onClose}>
      <div role="dialog" aria-modal="true" aria-label={title} className="modal">
        <h2>{title}</h2>
        {children}
        <button onClick={onClose} aria-label="Close">x</button>
      </div>
    </div>
  );
}
